"""Attachment storage interface."""

import re
from collections.abc import Iterator
from typing import IO, Final, Protocol

CHUNK_SIZE: Final = 64 * 1024
_KEY_PATTERN: Final = re.compile(r"^attachments/[0-9a-f]{32}$")


class BlobNotFoundError(Exception):
    """The metadata row exists but the stored bytes do not."""


def check_key(key: str) -> str:
    """Storage keys are generated by the service; anything else is a programming error."""
    if not _KEY_PATTERN.fullmatch(key):
        raise ValueError("invalid storage key")
    return key


class AttachmentStorage(Protocol):
    def save(self, key: str, data: IO[bytes], size: int) -> None:
        """Store ``size`` bytes read from ``data`` under ``key``."""
        ...

    def open(self, key: str) -> Iterator[bytes]:
        """Stream the stored bytes in chunks."""
        ...

    def delete(self, key: str) -> None: ...

    def check(self) -> None:
        """Raise if the backend is unusable. Used by the readiness probe."""
        ...
